import type { RunResult } from '../core/host'
import type { ChangedFile } from './changes'
import { changedFilesOf, numstatOf, statusEntriesOf } from './changes'
import type { Hunk } from './hunks'
import { hunksOf } from './hunks'
import { applyArgvOf } from './patch'

export type Run = (argv: readonly string[], stdin?: string) => Promise<RunResult>

/** A run's trimmed stdout when it exits 0, else null. */
export function outputOf(result: RunResult): string | null {
  return result.exitCode === 0 ? result.stdout.trim() : null
}

/** The repository's root, or null outside a git repository. */
export async function toplevelOf(run: Run): Promise<string | null> {
  return outputOf(await run(['git', 'rev-parse', '--show-toplevel']))
}

/** `existingPathsOf`'s own cap on paths per `git ls-files` call, so one very large candidate list still goes out as several ordinary-sized calls rather than one with an unbounded argv. */
export const EXISTENCE_CHUNK_SIZE = 200

/**
 * Which of `paths` (repository-toplevel-relative, the same frame every `ChangedFile.path` and
 * stored `Comment.path` is in) currently exist in the working tree (tracked or untracked)
 * batched `git ls-files` calls, `EXISTENCE_CHUNK_SIZE` paths per call rather than one per path
 * (or one unbounded call for every candidate at once). No `--exclude-standard`: the pathspec
 * already limits the listing to the candidates, so `--exclude-standard` would only ever drop a
 * candidate that is itself gitignored but still on disk: exactly the file this check must not
 * call gone. Run with `-C toplevel`, not the session's cwd: a pathspec is read relative to cwd,
 * and the session's cwd can sit below the toplevel, which would read every candidate as missing.
 * `--literal-pathspecs` also keeps a path containing `[`/`*`/`?` from being read as a glob.
 * `null` means the check itself failed (a non-zero exit, on any chunk): fail open, as if no
 * check had run, not that nothing exists; callers treat that the same as "unknown" elsewhere in
 * Raven, rather than risk calling a comment's file gone over an infra hiccup. `paths` empty needs
 * no call.
 */
export async function existingPathsOf(
  run: Run,
  toplevel: string,
  paths: readonly string[],
): Promise<ReadonlySet<string> | null> {
  if (paths.length === 0) return new Set()
  const existing = new Set<string>()
  for (let start = 0; start < paths.length; start += EXISTENCE_CHUNK_SIZE) {
    const chunk = paths.slice(start, start + EXISTENCE_CHUNK_SIZE)
    const result = await run([
      'git',
      '--literal-pathspecs',
      '-C',
      toplevel,
      'ls-files',
      '--cached',
      '--others',
      '-z',
      '--',
      ...chunk,
    ])
    if (result.exitCode !== 0) return null
    for (const token of result.stdout.split('\0')) if (token.length > 0) existing.add(token)
  }
  return existing
}

/** What the working tree is diffed against: `HEAD`, or a specific commit (a session start or a merge-base). */
export type Base = { kind: 'head' } | { kind: 'commit'; sha: string }

/** The git revision a base names, for a diff argv. */
export function refOf(base: Base): string {
  return base.kind === 'head' ? 'HEAD' : base.sha
}

/**
 * Reads the working tree's changes against `base`. Returns null outside a git repo.
 */
export async function loadChanges(
  run: Run,
  base: Base,
): Promise<{ toplevel: string; files: ChangedFile[] } | null> {
  // Outside a repository status and diff fail harmlessly, so all three start together.
  const [toplevel, status, diff] = await Promise.all([
    toplevelOf(run),
    run(['git', 'status', '--porcelain=v1', '-z', '--untracked-files=all']),
    run(['git', 'diff', refOf(base), '--numstat', '-z']),
  ])
  if (toplevel === null) return null
  const numstat = diff.exitCode === 0 ? numstatOf(diff.stdout) : new Map()
  const entries = statusEntriesOf(status.stdout)
  const files = changedFilesOf(entries, numstat, await untrackedLinesOf(run, entries))
  return { toplevel, files }
}

/** Past this many new files the list shows +0 for them rather than spawning a git per file. */
export const UNTRACKED_COUNT_LIMIT = 50

/** Line counts of untracked files, which `git diff HEAD` does not see. */
async function untrackedLinesOf(
  run: Run,
  entries: ReturnType<typeof statusEntriesOf>,
): Promise<Map<string, number>> {
  const paths = entries
    .filter(entry => entry.status === 'untracked')
    .slice(0, UNTRACKED_COUNT_LIMIT)
    .map(entry => entry.path)
  const counts = await Promise.all(
    paths.map(async path => {
      const result = await run(['git', 'diff', '--no-index', '--numstat', '--', '/dev/null', path])
      return [path, Number.parseInt(result.stdout, 10) || 0] as const
    }),
  )
  return new Map(counts)
}

/**
 * One file's hunks (all but a cut-off last one when the diff overran the output cap): tracked files diff against `base`, untracked files diff against /dev/null, and
 * a renamed file diffs with rename detection (`-M`) against both its old and new path: diffing
 * the new path alone would compare it against nothing at `base` and show the whole file as added.
 */
export async function loadHunks(
  run: Run,
  file: ChangedFile,
  base: Base,
): Promise<{ hunks: Hunk[]; isTruncated: boolean }> {
  const argv =
    file.status === 'untracked'
      ? ['git', 'diff', '--no-index', '--', '/dev/null', file.path]
      : file.status === 'renamed' && file.oldPath
        ? ['git', 'diff', '-M', refOf(base), '--', file.oldPath, file.path]
        : ['git', 'diff', refOf(base), '--', file.path]
  const result = await run(argv)
  const hunks = hunksOf(result.stdout)
  // A diff past the engine's output cap ends mid-hunk: drop that last hunk rather than show (or
  // let anyone stage) half of it.
  return result.isStdoutTruncated
    ? { hunks: hunks.slice(0, -1), isTruncated: true }
    : { hunks, isTruncated: false }
}

/**
 * The path a `diff --git` section changes: the rename target, the new file, else the old one.
 * git appends a tab to a ---/+++ name containing a space; it is not part of the path.
 */
function sectionPathOf(section: string): string | null {
  const path =
    /^rename to (.+)$/m.exec(section)?.[1] ??
    /^\+\+\+ b\/(.+)$/m.exec(section)?.[1] ??
    /^--- a\/(.+)$/m.exec(section)?.[1] ??
    /^diff --git a\/.+ b\/(.+)$/m.exec(section)?.[1]
  return path === undefined ? null : path.replace(/\t$/, '')
}

/** A multi-file `git diff` cut at its `diff --git` lines, keyed by the path each section changes. */
export function diffSectionsOf(diff: string): Map<string, string> {
  const sections = new Map<string, string>()
  for (const part of diff.split(/^(?=diff --git )/m)) {
    if (!part.startsWith('diff --git ')) continue
    const path = sectionPathOf(part)
    if (path !== null) sections.set(path, part)
  }
  return sections
}

export type LoadedHunks = {
  /**
   * Hunks per path; a path absent here was not read (an untracked file past the cap, or one
   * whose read failed).
   */
  byPath: ReadonlyMap<string, readonly Hunk[]>
  /** The file the output cap cut mid-diff (its last hunk dropped), or null. */
  truncatedPath: string | null
}

/** One file's `[path, hunks]` entry for `loadAllHunks`'s per-file reads; null on a rejected read, so one bad file leaves only itself unread rather than failing the whole call. */
async function oneHunksEntryOf(
  run: Run,
  file: ChangedFile,
  base: Base,
): Promise<readonly [string, readonly Hunk[]] | null> {
  try {
    return [file.path, (await loadHunks(run, file, base)).hunks]
  } catch {
    return null
  }
}

/**
 * Every changed file's hunks against `base`: one `git diff -M` for all tracked files (no
 * pathspec, so no argv limit), split per file; untracked files one `--no-index` read each, up to
 * `UNTRACKED_COUNT_LIMIT`. Past the 4 MiB output cap the cut file keeps its whole hunks and the
 * files after it are read together. A non-zero exit from the all-files diff (e.g. a bad
 * revision) throws rather than silently reading every tracked file as unchanged.
 */
export async function loadAllHunks(
  run: Run,
  files: readonly ChangedFile[],
  base: Base,
): Promise<LoadedHunks> {
  const tracked = files.filter(file => file.status !== 'untracked')
  const untracked = files
    .filter(file => file.status === 'untracked')
    .slice(0, UNTRACKED_COUNT_LIMIT)
  const byPath = new Map<string, readonly Hunk[]>()
  let truncatedPath: string | null = null

  if (tracked.length > 0) {
    const result = await run(['git', '-c', 'core.quotePath=false', 'diff', '-M', refOf(base)])
    if (result.exitCode !== 0) {
      throw new Error(`git diff failed: ${result.stderr.trim()}`)
    }
    const sections = [...diffSectionsOf(result.stdout)]
    sections.forEach(([path, section], index) => {
      const hunks = hunksOf(section)
      const isCut = result.isStdoutTruncated === true && index === sections.length - 1
      if (isCut) truncatedPath = path
      byPath.set(path, isCut ? hunks.slice(0, -1) : hunks)
    })
    const missing = tracked.filter(file => !byPath.has(file.path))
    if (result.isStdoutTruncated && missing.length > 0) {
      const reread = await Promise.all(missing.map(file => oneHunksEntryOf(run, file, base)))
      for (const entry of reread) if (entry) byPath.set(entry[0], entry[1])
    } else {
      for (const file of missing) byPath.set(file.path, [])
    }
  }

  const read = await Promise.all(untracked.map(file => oneHunksEntryOf(run, file, base)))
  for (const entry of read) if (entry) byPath.set(entry[0], entry[1])
  return { byPath, truncatedPath }
}

/** Stages or reverts one hunk's patch via `git apply`, reading it from stdin. */
export async function applyPatch(
  run: Run,
  patch: string,
  mode: 'stage' | 'revert',
): Promise<{ ok: boolean; error?: string }> {
  const result = await run(applyArgvOf(mode), patch)
  return result.exitCode === 0 ? { ok: true } : { ok: false, error: result.stderr.trim() }
}

files.hooks/review/comments.ts:
import { isRecord } from '../core/is-record'
import { bodyLinesOf, hunkLinesOf } from '../git/hunks'

/** A single diff line a comment anchors to, inside its `hunk`. */
export type CommentLine = { number: number; side: 'old' | 'new'; text: string }

/** Where a comment sits in the send/reply cycle: pending → sent → addressed, or open to resend. */
export type CommentStatus = 'pending' | 'sent' | 'addressed' | 'open'

export type Comment = {
  id: string
  path: string
  /** The '@@ -a,b +c,d @@' header of the hunk this anchors to; absent = whole-file comment. */
  hunk?: string
  line?: CommentLine
  /** The doc section a doc comment is on: its heading, or '(top)' before the first one. */
  section?: string
  /** That section's 0-based position in the doc when the comment was made. */
  sectionIndex?: number
  text: string
  status: CommentStatus
  createdAt: number
}
export type Comments = readonly Comment[]

type AddCommentInput = Omit<Comment, 'id' | 'status'> & { status?: CommentStatus }

/** Adds a comment, assigning it a unique id derived from its timestamp; status defaults to 'pending'. */
export function addComment(comments: Comments, input: AddCommentInput): Comments {
  const id = `${input.createdAt.toString(36)}-${comments.length}`
  return [...comments, { ...input, id, status: input.status ?? 'pending' }]
}

/** Removes a comment by id; a missing id leaves the list unchanged. */
export function removeComment(comments: Comments, id: string): Comments {
  return comments.filter(comment => comment.id !== id)
}

/** Comments anchored to a path and hunk; `hunk` undefined selects file-level ones only. */
export function commentsOn(comments: Comments, path: string, hunk?: string): Comments {
  return comments.filter(comment => comment.path === path && comment.hunk === hunk)
}

/**
 * Splits one anchor's comments into their addressed ones and the rest, each keeping its order:
 * the one implementation every anchor that collapses addressed comments into a single "✓ N
 * addressed" row (a diff anchor's `notesBlocksOf`, a doc section's own notes) builds on.
 */
export function splitAddressed(comments: Comments): { addressed: Comments; visible: Comments } {
  return {
    addressed: comments.filter(comment => comment.status === 'addressed'),
    visible: comments.filter(comment => comment.status !== 'addressed'),
  }
}

const PREAMBLE = "These are the user's review comments on files and docs. Address them."

/** "2nd", "3rd", "4th", …: the English ordinal suffix for `n` (`n` is always ≥ 2 here). */
function ordinalOf(n: number): string {
  if (n % 100 >= 11 && n % 100 <= 13) return `${n}th`
  const suffix = ['th', 'st', 'nd', 'rd'][n % 10] ?? 'th'
  return `${n}${suffix}`
}

function commentLinesOf(comment: Comment): string {
  const suffix = `[${comment.id}]`
  if (!comment.line) return `- ${comment.text} ${suffix}`
  const sign = comment.line.side === 'old' ? '-' : '+'
  return `L${comment.line.number} ${sign} ${comment.line.text}\n  - ${comment.text} ${suffix}`
}

/**
 * Renders the given comments as the model reads them: a short preamble saying these are the
 * user's review comments on files and docs, to address them; then grouped by file, each hunk's
 * comments under its header, a line-anchored comment quoting its diff line first; a doc's
 * comments group instead under `§ <section heading>`, in first-seen (by createdAt) order. Callers
 * pass whichever subset should be sent (typically the pending ones). Returns undefined for none.
 * Deterministic ordering: by path, file-level first, then by hunk in first-seen order, then
 * createdAt. Each comment ends with its id in brackets so a later reply can name which it addressed.
 */
export function reviewTextOf(comments: Comments): string | undefined {
  if (comments.length === 0) return undefined

  const paths = [...new Set(comments.map(comment => comment.path))].sort()
  const sections = paths.map(path => {
    const forPath = comments.filter(comment => comment.path === path)

    if (forPath.every(comment => comment.section !== undefined)) {
      const sorted = [...forPath].sort((a, b) => a.createdAt - b.createdAt)
      // Two sections can share a heading (duplicate headings in the doc); `sectionIndex`, when
      // present, keys them apart so their comments never merge into one group for Claude; the
      // heading text alone stays what Claude reads, a repeat just gets an ordinal suffix. A
      // legacy comment with no `sectionIndex` (made before that field existed) matches the first
      // section with its heading on screen (`doc-view.tsx`'s `sectionsBody`), so it groups the
      // same way here: as the first occurrence's index, when one exists for that heading.
      const firstIndexByHeading = new Map<string, number>()
      for (const comment of forPath) {
        if (comment.sectionIndex === undefined) continue
        const heading = comment.section as string
        const current = firstIndexByHeading.get(heading)
        if (current === undefined || comment.sectionIndex < current) {
          firstIndexByHeading.set(heading, comment.sectionIndex)
        }
      }
      const keyOf = (comment: Comment) => {
        const heading = comment.section as string
        const index = comment.sectionIndex ?? firstIndexByHeading.get(heading)
        return index !== undefined ? `${heading}\u0000${index}` : heading
      }
      // A group's order of appearance (first commented on) is independent of its ordinal label:
      // the label ranks groups by their `sectionIndex` ascending (the section's actual position
      // in the doc) so Claude reads "(2nd)" as "further down the doc", never "commented on
      // second".
      const indicesByHeading = new Map<string, number[]>()
      for (const comment of sorted) {
        if (comment.sectionIndex === undefined) continue
        const heading = comment.section as string
        const indices = indicesByHeading.get(heading) ?? []
        if (!indices.includes(comment.sectionIndex)) indices.push(comment.sectionIndex)
        indicesByHeading.set(heading, indices)
      }
      const rankOf = new Map<string, number>()
      for (const [heading, indices] of indicesByHeading) {
        const ascending = [...indices].sort((a, b) => a - b)
        ascending.forEach((index, i) => {
          rankOf.set(`${heading}\u0000${index}`, i + 1)
        })
      }

      const order = [...new Set(sorted.map(keyOf))]
      const groups = order.map(key => {
        const sample = sorted.find(comment => keyOf(comment) === key) as Comment
        const heading = sample.section as string
        const rank = sample.sectionIndex !== undefined ? (rankOf.get(key) ?? 1) : 1
        const label = rank === 1 ? heading : `${heading} (${ordinalOf(rank)})`
        const lines = sorted
          .filter(comment => keyOf(comment) === key)
          .map(commentLinesOf)
          .join('\n')
        return `§ ${label}\n${lines}`
      })
      return `${path}\n${groups.join('\n')}`
    }

    const seenHunks = [
      ...new Set(forPath.flatMap(comment => (comment.hunk === undefined ? [] : [comment.hunk]))),
    ]
    // Keeps file-level (hunk `undefined`) first; it can't be sorted in among the hunk headers.
    const hasFileLevel = forPath.some(comment => comment.hunk === undefined)
    const hunkOrder: (string | undefined)[] = hasFileLevel ? [undefined, ...seenHunks] : seenHunks

    const groups = hunkOrder.map(hunk => {
      const lines = forPath
        .filter(comment => comment.hunk === hunk)
        .sort((a, b) => a.createdAt - b.createdAt)
        .map(commentLinesOf)
        .join('\n')
      return hunk === undefined ? lines : `${hunk}\n${lines}`
    })

    return `${path}\n${groups.join('\n')}`
  })

  return `${PREAMBLE}\n\n${sections.join('\n\n')}`
}

/** The changed lines of a hunk, each with the real line number it has on its side of the diff. */
export function changedLinesOf(hunk: { header: string; text: string }): CommentLine[] {
  const body = bodyLinesOf(hunk)
  return hunkLinesOf(hunk).flatMap(({ index, kind, oldLine, newLine }): CommentLine[] => {
    const text = (body[index] ?? '').slice(1)
    if (kind === 'add') return [{ number: newLine, side: 'new', text }]
    if (kind === 'del') return [{ number: oldLine, side: 'old', text }]
    return []
  })
}

/** A line's identity within a hunk: its side and number. */
export const lineKeyOf = (line: Pick<CommentLine, 'number' | 'side'>): string =>
  `${line.side}:${line.number}`

/** A hunk line located by `lineRowsOf`: the body row it draws on and its text without the prefix. */
export type LineRow = { index: number; text: string }

/**
 * Where each line of `hunk` draws, by `lineKeyOf` (a context line on both its sides): one walk
 * per hunk, so many notes cost one lookup each. A line the hunk lacks is absent; the caller
 * compares `text` to know the line is still the one a note was made on.
 */
export function lineRowsOf(hunk: { header: string; text: string }): ReadonlyMap<string, LineRow> {
  const body = bodyLinesOf(hunk)
  const rows = new Map<string, LineRow>()
  for (const { index, kind, oldLine, newLine } of hunkLinesOf(hunk)) {
    const found = { index, text: (body[index] ?? '').slice(1) }
    if (kind !== 'add') rows.set(lineKeyOf({ side: 'old', number: oldLine }), found)
    if (kind !== 'del') rows.set(lineKeyOf({ side: 'new', number: newLine }), found)
  }
  return rows
}

/** One file's comments split against its current hunks: file-level, live per-hunk, and outdated. */
export function groupByAnchor(
  comments: Comments,
  currentHunkHeaders: readonly string[],
): { file: Comment[]; byHunk: Map<string, Comment[]>; outdated: Comment[] } {
  const current = new Set(currentHunkHeaders)
  const file: Comment[] = []
  const byHunk = new Map<string, Comment[]>()
  const outdated: Comment[] = []

  for (const comment of comments) {
    if (comment.hunk === undefined) {
      file.push(comment)
    } else if (current.has(comment.hunk)) {
      const forHunk = byHunk.get(comment.hunk)
      if (forHunk) forHunk.push(comment)
      else byHunk.set(comment.hunk, [comment])
    } else {
      outdated.push(comment)
    }
  }

  return { file, byHunk, outdated }
}

function jsonArrayOf(candidate: string): unknown[] | null {
  try {
    const parsed = JSON.parse(candidate)
    return Array.isArray(parsed) ? parsed : null
  } catch {
    return null
  }
}

/** Parses a reply expected to carry a JSON array, tolerating a fence or prose around it. */
function arrayIn(reply: string): unknown[] {
  const fenced = reply.match(/```(?:json)?\s*([\s\S]*?)```/)
  if (fenced?.[1]) {
    const parsed = jsonArrayOf(fenced[1].trim())
    if (parsed) return parsed
  }
  for (const candidate of reply.match(/\[[^[\]]*\]/g) ?? []) {
    const parsed = jsonArrayOf(candidate)
    if (parsed) return parsed
  }
  return []
}

/** Parses a model reply expected to name addressed comment ids, keeping only ids actually sent. */
export function addressedIdsOf(reply: string, sentIds: readonly string[]): string[] {
  const known = new Set(sentIds)
  const ids = arrayIn(reply).filter((id): id is string => typeof id === 'string' && known.has(id))
  return [...new Set(ids)]
}

const STATUSES: readonly CommentStatus[] = ['pending', 'sent', 'addressed', 'open']

function statusOf(value: unknown): CommentStatus {
  return typeof value === 'string' && (STATUSES as readonly string[]).includes(value)
    ? (value as CommentStatus)
    : 'pending'
}

function lineOf(value: unknown): CommentLine | null {
  if (!isRecord(value)) return null
  const { number, side, text } = value
  if (typeof number !== 'number' || !Number.isFinite(number)) return null
  if (side !== 'old' && side !== 'new') return null
  if (typeof text !== 'string') return null
  return { number, side, text }
}

function commentOf(value: unknown): Comment | null {
  if (!isRecord(value)) return null
  const { id, path, hunk, line, section, sectionIndex, text, createdAt } = value
  if (typeof id !== 'string' || typeof path !== 'string' || typeof text !== 'string') return null
  if (typeof createdAt !== 'number' || !Number.isFinite(createdAt)) return null
  if (hunk !== undefined && typeof hunk !== 'string') return null
  const parsedLine = line === undefined ? undefined : lineOf(line)
  if (line !== undefined && parsedLine === null) return null
  if (section !== undefined && typeof section !== 'string') return null
  if (
    sectionIndex !== undefined &&
    (typeof sectionIndex !== 'number' || !Number.isInteger(sectionIndex) || sectionIndex < 0)
  )
    return null

  const comment: Comment = { id, path, text, createdAt, status: statusOf(value.status) }
  if (hunk !== undefined) comment.hunk = hunk
  if (parsedLine) comment.line = parsedLine
  if (section !== undefined) comment.section = section
  if (sectionIndex !== undefined) comment.sectionIndex = sectionIndex
  return comment
}

/** Parses a stored value back into Comments, dropping malformed entries; a missing status reads as 'pending'. */
export function commentsFrom(value: unknown): Comments {
  if (!Array.isArray(value)) return []
  return value.flatMap(entry => {
    const comment = commentOf(entry)
    return comment ? [comment] : []
  })
}

