import type { UiKit } from '../core/view'

/** Nerd Font icons the empty states use. */
export const EMPTY_ICONS = {
  doc: '\u{f0219}', // nf-md-file_document
  tasks: '\u{f0ae}', // nf-fa-tasks
  changes: '\u{f02a2}', // nf-md-git
