  const { Box, Text } = kit.ui
  return (
    <Box key="empty" flexDirection="column" paddingTop={1} paddingLeft={2}>
      <Text dimColor wrap="truncate-end">
        {`${icon}  ${text}`}
      </Text>
    </Box>
  )
}

